function roomCount(meetings: number[][]): number {
  // meetings are half-open [start, end). Return the fewest rooms that fit all of them.
  return meetings.length > 0 ? 1 : 0;
}

console.log(roomCount([[10, 40], [15, 25], [20, 50], [30, 35], [45, 60]]));

solution:
function roomCount(meetings: number[][]): number {
  const starts = meetings.map((m) => m[0]).sort((a, b) => a - b);
  const ends = meetings.map((m) => m[1]).sort((a, b) => a - b);
  let rooms = 0;
  let j = 0;
  for (const s of starts) {
    if (s >= ends[j]) j++;
    else rooms++;
  }
  return rooms;
}
